function initSunoLauncher(){const t=currentTrack();const chip=$('#launchTrackChip'),nameEl=$('#launchArtistName'),promptEl=$('#launchPrompt'),modeEl=$('#launchMode');if(!chip)return;if(!t||!t.id){if(chip)chip.textContent='Select a track';if(promptEl)promptEl.value='';if(nameEl)nameEl.textContent='—';return;}const dna=ARTIST_DNA[t.artist]||{};if(chip)chip.textContent=t.title+' · '+t.artist;if(nameEl)nameEl.textContent=t.artist;if(modeEl)modeEl.textContent=_launchMode==='vocal'?'VOCAL':'INSTRUMENTAL';if(promptEl)promptEl.value=_launchMode==='vocal'?(dna.style||'No DNA found for this artist'):(dna.instrumental||dna.style||'No instrumental DNA found');const copyV=$('#launchCopyVocal'),copyI=$('#launchCopyInstrumental'),toggle=$('#launchToggleMode'),logBtn=$('#launchLogResult');if(copyV)copyV.onclick=()=>{navigator.clipboard.writeText(dna.style||'');toast('Vocal prompt copied');};if(copyI)copyI.onclick=()=>{navigator.clipboard.writeText(dna.instrumental||dna.style||'');toast('Instrumental prompt copied');};if(toggle)toggle.onclick=()=>{_launchMode=_launchMode==='vocal'?'instrumental':'vocal';initSunoLauncher();};if(logBtn)logBtn.onclick=()=>{const sunoUrl=$('#launchResultUrl')?.value.trim();const audioUrl=$('#launchAudioUrl')?.value.trim();if(!sunoUrl&&!audioUrl){toast('Paste at least one URL');return;}const track=data.tracks.find(x=>x.id===t.id);if(!track)return;if(!track.generations)track.generations=[];const num=String(track.generations.length+1).padStart(2,'0');track.generations.push({code:'G'+num,name:t.title,note:'Generated in Suno · '+_launchMode,state:'REVIEW',audioUrl:audioUrl||'',sunoUrl:sunoUrl||'',loggedAt:new Date().toISOString()});save();renderGenerations();const logState=$('#launchLogState');if(logState)logState.textContent='Logged as G'+num+' · '+new Date().toLocaleTimeString();toast('Generation G'+num+' logged');};}

