function renderCatalogue(){if(!$('#catalogueTable'))return;const search=($('#catalogueSearch').value||'').trim().toLowerCase(),artistFilter=$('#catalogueArtist').value,statusFilter=$('#catalogueStatus').value,attentionOnly=$('#catalogueNeedsAttention').checked,artists=[...new Set(data.tracks.map(t=>t.artist).filter(Boolean))].sort(),statuses=[...new Set(data.tracks.map(t=>t.status||'Unclassified'))].sort();$('#catalogueArtist').innerHTML='<option value="">All artists</option>'+artists.map(name=>`<option value="${name}">${name}</option>`).join('');$('#catalogueStatus').innerHTML='<option value="">All statuses</option>'+statuses.map(status=>`<option value="${status}">${status}</option>`).join('');$('#catalogueArtist').value=artists.includes(artistFilter)?artistFilter:'';$('#catalogueStatus').value=statuses.includes(statusFilter)?statusFilter:'';const filtered=data.tracks.filter(t=>{const haystack=`${t.title||''} ${t.artist||''} ${t.id||''}`.toLowerCase(),status=t.status||'Unclassified';return (!search||haystack.includes(search))&&(!artistFilter||t.artist===artistFilter)&&(!statusFilter||status===statusFilter)&&(!attentionOnly||catalogueNeedsWork(t))}),rightsReady=data.tracks.filter(t=>t.rightsData?.length&&t.rightsData.every(r=>r[1])).length,attention=data.tracks.filter(catalogueNeedsWork).length,visible=filtered.slice(0,150);$('#catalogueTracks').textContent=data.tracks.length;$('#catalogueArtists').textContent=artists.length;$('#catalogueBlack').textContent=data.tracks.filter(t=>Number(t.score||0)>=95).length;$('#catalogueRights').textContent=rightsReady;$('#catalogueAttention').textContent=attention;$('#catalogueVisible').textContent=`${filtered.length} VISIBLE`;$('#catalogueTable').innerHTML=`<div class="catalogue-row head"><span>Recording</span><span>Artist</span><span>Status</span><span>QC</span><span>Rights</span><span>Source</span><span>Action</span></div>`+(visible.length?visible.map(t=>{const complete=t.rightsData?.length&&t.rightsData.every(r=>r[1]),done=(t.rightsData||[]).filter(r=>r[1]).length,total=(t.rightsData||[]).length;return `<div class="catalogue-row ${t.id===selectedTrackId?'selected':''}"><div class="catalogue-title"><b>${t.title||'Untitled recording'}</b><small>${t.id||'NO ID'}</small></div><b>${t.artist||'UNASSIGNED'}</b><span class="catalogue-status">${t.status||'UNCLASSIFIED'}</span><span class="catalogue-score">${Number(t.score||0)||'—'}</span><span class="catalogue-rights ${complete?'pass':'fail'}">${done}/${total||12}</span><span class="catalogue-source">${t.wpSynced?'WORDPRESS':'SIGNAL OS'}</span><button class="button ghost small" data-catalogue-track="${t.id}">Open track</button></div>`}).join(''):'<p class="catalogue-empty">No recordings match these filters.</p>');$('#catalogueNote').textContent=filtered.length>150?`Showing the first 150 of ${filtered.length} matches. Narrow the filters to see a specific recording.`:`Showing ${filtered.length} catalogue record${filtered.length===1?'':'s'}.`;$$('[data-catalogue-track]').forEach(button=>button.onclick=()=>{selectedTrackId=button.dataset.catalogueTrack;data.selectedTrackId=selectedTrackId;save();renderTrackContext();navigate('track')})}
