function renderArtist(id){const a=data.artists.find(x=>x.id===id);if(!a)return;$$('.artist-card').forEach(c=>c.classList.toggle('active',c.dataset.id===id));const profiles=artistProfileDefs.map(([name,key])=>[name,safeProfileUrl(a[key])]),linked=profiles.filter(([,url])=>url);const pf=(label,val,key)=>val?`<div class="canon-field wide prompt-field"><div class="prompt-field-head"><small>${label}</small><button class="button ghost small copy-aprompt" data-pk="${key}">Copy</button></div><p class="prompt-text">${val.replace(/</g,'&lt;')}</p></div>`:'';$('#artistEditor').innerHTML=`<div class="editor-header"><div><p class="eyebrow">${a.id}</p><h2>${a.name}</h2><small>${a.origin}${a.realName?' · '+a.realName:''}</small></div><div class="editor-actions"><button class="button ghost small" id="editArtist">Edit Bible</button><button class="button ghost small" id="pushArtistSite" title="Push to nairamusic.com">↑ Site</button>${a.status!=='LOCKED'?'<button class="button small" id="lockArtist">Lock canon</button>':''}<span class="status">${a.status}</span>${a.wpSynced?'<span class="tag" style="color:var(--green);border-color:#28583a">SITE ✓</span>':''}</div></div>${(a.signature||a.language||a.age||a.collaborations)?`<div class="artist-quick-info">${a.signature?`<span><small>Signature</small><b>${a.signature}</b></span>`:''}${a.age?`<span><small>Age</small><b>${a.age}</b></span>`:''}${a.language?`<span><small>Languages</small><b>${a.language}</b></span>`:''}${a.collaborations?`<span><small>Collaborations</small><b>${a.collaborations}</b></span>`:''}</div>`:''}<div class="canon-grid">${[['Archetype',a.archetype],['NMC role',a.role],['Vocal identity',a.voice],['Visual identity',a.visual],['Themes',a.themes],['Production rules',a.rules],['Prohibited overlap',a.prohibited]].map(([k,v],i)=>`<div class="canon-field ${i>1?'wide':''}"><small>${k}</small><p>${v||'—'}</p></div>`).join('')}${a.backstory?'<div class="canon-field wide canon-backstory"><p class="eyebrow">BACKSTORY</p><p>'+a.backstory+'</p></div>':''}${a.instruments?`<div class="canon-field wide"><small>Instruments for Suno</small><p>${a.instruments}</p></div>`:''}${pf('Music Generation Prompt',a.musicPrompt,'musicPrompt')}${pf('Instrumental Prompt',a.instrumentalPrompt,'instrumentalPrompt')}${pf('Literary / Narrative Prompt',a.literaryPrompt,'literaryPrompt')}<div class="canon-field wide"><small>Digital profiles · ${linked.length}/${profiles.length} linked</small><div class="artist-profile-links">${profiles.map(([name,url])=>url?`<a href="${url}" target="_blank" rel="noopener noreferrer">${name} ↗</a>`:`<span>${name} · awaiting URL</span>`).join('')}</div></div></div>`;$('#editArtist').onclick=()=>openArtistDialog(a);$('#pushArtistSite').onclick=()=>syncArtistToWP(a.id);$$('.copy-aprompt').forEach(btn=>btn.onclick=async()=>{const k=btn.dataset.pk;await navigator.clipboard.writeText(a[k]||'');toast(`${k==='musicPrompt'?'Music':k==='instrumentalPrompt'?'Instrumental':'Literary'} prompt copied`)});if($('#lockArtist'))$('#lockArtist').onclick=()=>{a.status='LOCKED';save();renderArtists();renderOverview();toast(`${a.name} canon locked by Naira Music`)}}
