function renderScores(){const scores=currentTrack().scores;$('#scoreControls').innerHTML=criteria.map(([k,n,m])=>`<div class="score-row"><div><b>${n}</b><small>Maximum ${m} points</small></div><input type="range" aria-label="${n} score" min="0" max="${m}" value="${scores[k]}" data-score="${k}"><span class="score-value" id="v-${k}">${scores[k]}</span></div>`).join('');$$('[data-score]').forEach(i=>i.oninput=()=>{scores[i.dataset.score]=+i.value;$('#v-'+i.dataset.score).textContent=i.value;updateScore()});updateScore()}
function updateScore(){const t=currentTrack(),scores=t.scores,total=Object.values(scores).reduce((a,b)=>a+b,0);let grade=total>=95?'BLACK SIGNAL':total>=90?'GOLD SIGNAL':total>=85?'GREEN SIGNAL':total>=75?'AMBER SIGNAL':'RED SIGNAL';$('#totalScore').textContent=total;$('#gradeBadge').innerHTML=`<strong>${total}</strong><span>${grade}</span>`;$('#gradeTitle').textContent=grade;$('#scoreRing').style.background=`conic-gradient(var(--gold) ${total}%,#222 0)`;$('#gradeText').textContent=total>=95?'Flagship quality. Eligible for priority release.':total>=90?'Official-single quality. Resolve remaining weaknesses before flagship classification.':total>=85?'Rotation ready, but not yet priority-release quality.':'Revision required before release.';const gates=[['Hook ≥ 18',scores.hook>=18],['Identity ≥ 13',scores.identity>=13],['Rights complete',t.rightsData.every(r=>r[1])],['Total ≥ 95',total>=95]];$('#gateList').innerHTML=gates.map(([n,p])=>`<div class="gate"><span>${n}</span><b class="${p?'pass':'fail'}">${p?'PASS':'BLOCKED'}</b></div>`).join('');return total}$('#saveScore').onclick=()=>{const t=currentTrack(),scores=t.scores;$$('[data-score]').forEach(i=>{scores[i.dataset.score]=+i.value;$('#v-'+i.dataset.score).textContent=i.value});const total=updateScore();t.score=total;t.status=total>=85?'Rights Check':'QC Review';save();renderOverview();renderPipeline();renderRotation();toast(`${t.title} QC decision saved`)};
function renderRights(){const rights=currentTrack().rightsData;$('#rightsLedger').innerHTML=rights.map((r,i)=>`<div class="ledger-row"><button class="check" aria-label="${r[1]?'Mark incomplete':'Mark complete'}: ${r[0]}" data-right="${i}">${r[1]?'✓':''}</button><b>${r[0]}</b><small>${r[2]}</small><span class="${r[1]?'pass':'fail'}">${r[1]?'COMPLETE':'BLOCKED'}</span></div>`).join('');$$('[data-right]').forEach(b=>b.onclick=()=>{const r=rights[+b.dataset.right];r[1]=!r[1];if(r[1]&&r[2]==='Required')r[2]='Confirmed';save();renderRights();renderOverview();updateScore()})}$('#markRights').onclick=()=>{const t=currentTrack();t.rightsData.forEach(r=>{r[1]=true;if(r[2]==='Required')r[2]='Confirmed'});save();renderRights();renderOverview();updateScore();toast(`${t.title} provenance complete`)};
const columns=['Concept','Suno Generation','QC Review','Rights Check','Scheduled'];function renderScheduler(){const list=$('#schedulerList');if(!list)return;const nmc=data.tracks.filter(t=>!t.wpSynced).sort((a,b)=>{const ra=a.releaseMetadata?.releaseDate||'',rb=b.releaseMetadata?.releaseDate||'';if(ra&&rb)return ra.localeCompare(rb);if(ra)return -1;if(rb)return 1;return a.artist.localeCompare(b.artist)||a.title.localeCompare(b.title);});list.innerHTML='<div class="scheduler-list">'+nmc.map((t,i)=>{const d=t.releaseMetadata?.releaseDate||'';const g=t.releaseMetadata?.genre||'';return `<div class="scheduler-row" data-sched-id="${t.id}"><span class="scheduler-num">${String(i+1).padStart(2,'0')}</span><div class="scheduler-info"><b>${t.title}</b><small>${t.artist}</small></div><span class="scheduler-genre">${g}</span><div class="scheduler-date"><input type="date" value="${d}" data-sched-track="${t.id}" ${d?'class="date-set"':''}></div></div>`}).join('')+'</div>';$$('[data-sched-track]').forEach(inp=>inp.oninput=()=>{inp.classList.toggle('date-set',!!inp.value);});$('#staggerApply').onclick=()=>{const start=new Date($('#staggerStart').value);if(isNaN(start))return toast('Set a start date first');const gap=Number($('#staggerGap').value||14);$$('[data-sched-track]').forEach((inp,i)=>{const d=new Date(start);d.setDate(d.getDate()+i*gap);inp.value=d.toISOString().slice(0,10);inp.classList.add('date-set');});toast('Dates staggered — review and save');};$('#saveAllDates').onclick=()=>{let saved=0;$$('[data-sched-track]').forEach(inp=>{if(!inp.value)return;const t=data.tracks.find(x=>x.id===inp.dataset.schedTrack);if(!t)return;if(!t.releaseMetadata)t.releaseMetadata={title:t.title,artist:t.artist,version:'',releaseType:'Single',genre:'',secondaryGenre:'',language:'',explicit:'Explicit',pLine:'',cLine:'',songwriters:'',producers:'',releaseDate:'',territories:'Worldwide',label:'Naira Music',catalogue:t.id,locked:false};t.releaseMetadata.releaseDate=inp.value;saved++;});save();renderScheduler();renderPipeline();toast(saved+' release dates saved');};}function renderPipeline(){$('#kanban').innerHTML=columns.map(c=>`<section class="column"><div class="column-head"><span>${c}</span><span>${data.tracks.filter(t=>t.status===c).length}</span></div>${data.tracks.filter(t=>t.status===c).map(t=>`<article class="track-card"><b>${t.title}</b><small>${t.artist} · ${t.id}</small><div class="card-foot"><span class="tag">${t.status}</span><span class="mini-score">${t.score||'—'}</span></div>${t.status!=='Scheduled'?`<button type="button" class="pipeline-advance" data-advance-track="${t.id}">Advance to ${columns[columns.indexOf(t.status)+1]} →</button>`:''}</article>`).join('')}</section>`).join('');$$('[data-advance-track]').forEach(b=>b.onclick=()=>{const t=data.tracks.find(x=>x.id===b.dataset.advanceTrack);const i=columns.indexOf(t.status);t.status=columns[Math.min(i+1,columns.length-1)];save();renderPipeline();renderOverview();toast(`Moved to ${t.status}`)})}$('#newTrack').onclick=()=>$('#trackDialog').showModal();$('#cancelTrack').onclick=$('#closeTrack').onclick=()=>$('#trackDialog').close();$('#newTrackForm').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),id='NMC-TRACK-'+String(data.tracks.length+1).padStart(3,'0'),track={id,title:f.title,artist:f.artist,emotion:f.emotion,status:'Concept',score:0,rotation:'E',scores:structuredClone(blankScores),rightsData:baseRights(f.title,f.artist),generations:[],dna:{title:f.title,artist:f.artist,emotion:f.emotion,explicit:'Explicit',conflict:'',transformation:'',hook:'',anchor:'',purpose:'',bpm:138,key:'D minor',risks:''}};data.tracks.push(track);selectedTrackId=id;data.selectedTrackId=id;save();renderPipeline();renderOverview();renderRotation();renderTrackContext();$('#trackDialog').close();e.target.reset();toast(`${f.title} Track DNA started`)};
const rotationTiers=[['A1','Signal Priority','Flagship and launch records'],['A2','Heavy Rotation','Proven audience response'],['B','Discovery','New and developing releases'],['C','Catalogue','Long-tail library'],['D','Night Frequency','Dark or explicit programming'],['E','Test Signal','Limited audience testing']];function renderRotation(){data.tracks.forEach(t=>{if(!t.rotation)t.rotation=t.score>=95?'A1':t.score>=90?'B':'E'});$('#rotationBoard').innerHTML=rotationTiers.map(([code,name,note])=>`<section class="tier"><div class="tier-head"><div><span>${code}</span><h2>${name}</h2></div><small>${note}</small></div>${data.tracks.filter(t=>t.rotation===code).map(t=>`<article class="rotation-track"><b>${t.title}</b><small>${t.artist} · ${t.score||'Unscored'}</small><select aria-label="Rotation tier for ${t.artist} — ${t.title}" data-rotation="${t.id}">${rotationTiers.map(([c,n])=>`<option value="${c}" ${c===code?'selected':''}>${c} — ${n}</option>`).join('')}</select></article>`).join('')}</section>`).join('');$$('[data-rotation]').forEach(s=>s.onchange=()=>{data.tracks.find(t=>t.id===s.dataset.rotation).rotation=s.value;save();renderRotation();toast(`Rotation moved to ${s.value}`)})}
