let _radioData=null,_countdownInterval=null;
function fmtSecs(s){const m=Math.floor(s/60),r=s%60;return`${m}:${String(r).padStart(2,'0')}`}
function startCountdown(remaining){clearInterval(_countdownInterval);let s=Math.max(0,Math.round(remaining));const el=$('#radioCountdown');if(!el)return;el.textContent=`next in ${fmtSecs(s)}`;_countdownInterval=setInterval(()=>{s=Math.max(0,s-1);if(el)el.textContent=`next in ${fmtSecs(s)}`;if(s===0){clearInterval(_countdownInterval);setTimeout(renderRadio,1200)}},1000)}
async function renderRadio(){
  const dot=$('#radioDot'),status=$('#radioLiveStatus');
  if(dot)dot.className='radio-status-dot';
  try{
    const d=await api('/api/radio/status');
    _radioData=d;
    const r=d.radio||{};
    const ci=r.current_item||{},ni=r.next_item||{};
    // Now playing
    if($('#radioNowTitle'))$('#radioNowTitle').textContent=ci.title||'—';
    if($('#radioNowArtist'))$('#radioNowArtist').textContent=ci.artist_name||'—';
    if($('#radioNowMeta'))$('#radioNowMeta').textContent=[ci.genre,ci.bpm?ci.bpm+' BPM':'',ci.duration?fmtSecs(ci.duration):''].filter(Boolean).join(' · ')||'No metadata';
    if($('#radioCoverWrap')){
      if(ci.cover){$('#radioCoverWrap').innerHTML=`<img class="radio-cover" src="${ci.cover}" alt="${ci.title}" loading="lazy">`;}
      else{$('#radioCoverWrap').textContent='♫';$('#radioCoverWrap').className='radio-cover-placeholder';}
    }
    // Next
    if($('#radioNextTitle'))$('#radioNextTitle').textContent=ni.title||'—';
    if($('#radioNextArtist'))$('#radioNextArtist').textContent=ni.artist_name||'—';
    // Countdown
    startCountdown(r.remaining||0);
    // Stats
    if($('#radioTrackCount'))$('#radioTrackCount').textContent=d.track_count||r.playlist_length||'—';
    if($('#radioPlaylistLen'))$('#radioPlaylistLen').textContent=r.playlist_length?r.playlist_length+' slots':'—';
    if($('#radioShowName'))$('#radioShowName').textContent=r.current_show?.name||'—';
    // Listeners — proxied through server to avoid CSP block
    api('/api/radio/listeners').then(c=>{if($('#radioListeners'))$('#radioListeners').textContent=c.count??'—'}).catch(()=>{});
    // Live badge
    if(status){status.textContent='LIVE';dot.className='radio-status-dot';}
    // Pending queue
    const pending=d.pending||[];
    const pendEl=$('#pendingCount');
    if(pendEl){if(pending.length){pendEl.textContent=pending.length+' PENDING';pendEl.style.display=''}else{pendEl.style.display='none'}}
    const qEl=$('#radioQueue');
    if(qEl){
      if(!pending.length){
        qEl.innerHTML='<p class="radio-empty">No drafts pending — use Automation → Record &amp; Push to queue a track here.</p>';
      } else {
        qEl.innerHTML=pending.map(p=>`<div class="radio-queue-row"><div><div class="radio-queue-title">${p.title}</div><div class="radio-queue-artist">${p.artist||'—'}</div><div class="radio-queue-meta">BPM ${p.bpm||'—'} · synced ${p.synced_at||'—'}</div></div><div class="radio-queue-actions">${p.suno_url?`<a href="${p.suno_url}" target="_blank" rel="noopener" class="button ghost small">▶ Play</a>`:''}<a href="${p.edit_url}" target="_blank" rel="noopener" class="button ghost small">Edit</a><button class="radio-publish-btn" data-post-id="${p.post_id}">Publish to Radio →</button></div></div>`).join('');
        $$('.radio-publish-btn').forEach(btn=>btn.onclick=async()=>{
          const postId=btn.dataset.postId;
          btn.disabled=true;btn.textContent='Publishing…';
          try{
            const result=await api('/api/radio/publish',{method:'POST',body:JSON.stringify({post_id:parseInt(postId,10)})});
            toast(result.message||'Track live on radio!');
            logActivity('PUBLISHED TO RADIO',`Post #${postId} → NMC Signal rotation`);
            await renderRadio();
          }catch(e){toast(e.message);btn.disabled=false;btn.textContent='Publish to Radio →';}
        });
      }
    }
  }catch(e){
    if(status){status.textContent='OFFLINE';if(dot)dot.className='radio-status-dot offline';}
    if($('#radioNowTitle'))$('#radioNowTitle').textContent='Cannot reach NairaMusic.com';
    toast('Radio status unavailable: '+e.message);
  }
}
