async function syncArtistsFromWP(){try{const result=await api('/api/site/artists');if(result.dryRun)return toast('NMC_SIGNAL_KEY not configured — check server .env');const wpArtists=result.artists||[];let merged=0;wpArtists.forEach(wa=>{const ex=data.artists.find(a=>a.name.toLowerCase()===wa.name.toLowerCase()||a.wpPostId===wa.id);if(ex){ex.wpPostId=wa.id;ex.wpSynced=true;if(!ex.thumbnailUrl)ex.thumbnailUrl=wa.thumbnail;merged++;}});save();renderArtists();logActivity('ARTISTS SYNCED FROM SITE',`${wpArtists.length} on nairamusic.com · ${merged} matched in SIGNAL//OS`);toast(`Site sync: ${merged}/${wpArtists.length} artists matched`)}catch(error){toast(`Sync failed: ${error.message}`)}}
