// ── TRACK SYNC FROM WP ──────────────────────────────────────────────────────
// Map WP artist names (mixed case) → canonical NMC names (UPPERCASE)
const _wpArtistNorm={'pastor flow':'PASTOR FLOW','asa brugga':'ASA BRUGGA','dj nah lie':'DJ NA LIE','dj na lie':'DJ NA LIE','nova venom':'NOVA VENOM','lyrikal flame':'LYRIKAL FLAME','boboyi':'BOBOYI','zooboi':'ZOOBOI','makasi':'MAKASI','fantasma':'FANTASMA','reign':'REIGN','nmc signal':'NMC SIGNAL','nmc':'NMC'};
function _normArtist(name){return _wpArtistNorm[name.toLowerCase().trim()]||name.toUpperCase().trim()||'NMC';}
// Map slug prefixes → canonical artist names
const _slugMap={'pastor-flow':'PASTOR FLOW','asa-brugga':'ASA BRUGGA','dj-nah':'DJ NA LIE','dj-na':'DJ NA LIE','nova-venom':'NOVA VENOM','lyrikal-flame':'LYRIKAL FLAME','boboyi':'BOBOYI','zooboi':'ZOOBOI','makasi':'MAKASI','fantasma':'FANTASMA','reign':'REIGN'};
function _artistFromSlug(slug){if(!slug)return '';const parts=slug.split('-');const two=parts.slice(0,2).join('-');if(_slugMap[two])return _slugMap[two];const one=parts[0];return _slugMap[one]||'';}
// Returns true if artist a is "better" (more specific) than b
function _betterArtist(a,b){return a&&a!=='NMC'&&(!b||b==='NMC');}
// De-duplicate data.tracks in-place: match on normalised title, keep best artist + richest data
function _deduplicateTracks(){
  const seen=new Map(); // titleKey → index in data.tracks
  const toRemove=new Set();
  data.tracks.forEach((t,i)=>{
    const key=(t.title||'').toLowerCase().trim();
    if(!key){toRemove.add(i);return;}
    if(!seen.has(key)){seen.set(key,i);return;}
    const keepIdx=seen.get(key),dupIdx=i;
    const keep=data.tracks[keepIdx],dup=data.tracks[dupIdx];
    // Merge dup data into keep, then drop dup
    if(_betterArtist(dup.artist,keep.artist))keep.artist=dup.artist;
    if(dup.audioUrl&&!keep.audioUrl)keep.audioUrl=dup.audioUrl;
    if(dup.coverUrl&&!keep.coverUrl)keep.coverUrl=dup.coverUrl;
    if(dup.streams&&!keep.streams)keep.streams=dup.streams;
    if(dup.genre&&!keep.genre)keep.genre=dup.genre;
    if(dup.bpm&&!keep.bpm)keep.bpm=dup.bpm;
    if(dup.wpPostId&&!keep.wpPostId)keep.wpPostId=dup.wpPostId;
    if(dup.wpSynced)keep.wpSynced=true;
    // Prefer WP-{id} over WP-PLY-{random} as canonical id
    if(dup.id&&!dup.id.startsWith('WP-PLY-')&&keep.id.startsWith('WP-PLY-'))keep.id=dup.id;
    toRemove.add(dupIdx);
  });
  if(toRemove.size){data.tracks=data.tracks.filter((_,i)=>!toRemove.has(i));return toRemove.size;}
  return 0;
}
async function syncTracksFromWP(silent=false){
  try{
    const[cat,playlist]=await Promise.allSettled([
      api('/api/site/catalogue'),
      api('/api/radio/playlist')
    ]);
    let added=0,updated=0;
    // Merge catalogue tracks (correct artist from ACF field)
    if(cat.status==='fulfilled'&&!cat.value.dryRun){
      (cat.value.tracks||[]).forEach(wt=>{
        const resolvedArtist=_normArtist(wt.artist||'NMC');
        const titleKey=(wt.title||'').toLowerCase().trim();
        if(!titleKey)return;
        // Match on title only — artist may differ (NMC vs real name)
        const ex=data.tracks.find(t=>(t.title||'').toLowerCase().trim()===titleKey);
        if(!ex){
          data.tracks.push({id:'WP-'+wt.id,wpPostId:wt.id,title:wt.title,artist:resolvedArtist,status:wt.status==='publish'?'QC Review':'Suno Generation',score:0,rotation:wt.featured?'A2':'B',streams:wt.streams||0,genre:wt.genre||'',bpm:wt.bpm||'',audioUrl:wt.audio_url||'',wpSynced:true,scores:structuredClone(blankScores),rightsData:baseRights(wt.title,resolvedArtist),generations:[],dna:{title:wt.title,artist:resolvedArtist,emotion:'',explicit:'Explicit',conflict:'',transformation:'',hook:'',anchor:'',purpose:'',bpm:Number(wt.bpm)||138,key:'',risks:''}});
          added++;
        } else {
          ex.wpPostId=wt.id;ex.wpSynced=true;
          if(_betterArtist(resolvedArtist,ex.artist))ex.artist=resolvedArtist;
          if(wt.streams)ex.streams=wt.streams;
          if(wt.audio_url&&!ex.audioUrl)ex.audioUrl=wt.audio_url;
          if(wt.genre&&!ex.genre)ex.genre=wt.genre;
          updated++;
        }
      });
    }
    // Merge playlist tracks — fills audio URLs and covers
    if(playlist.status==='fulfilled'){
      (playlist.value.playlist||[]).forEach(pt=>{
        const rawArtist=pt.artist_name||pt.artist||'';
        const resolvedArtist=rawArtist?_normArtist(rawArtist):(_artistFromSlug(pt.slug)||'NMC');
        const titleKey=(pt.title||'').toLowerCase().trim();
        if(!titleKey)return;
        // Match on title only
        const ex=data.tracks.find(t=>(t.title||'').toLowerCase().trim()===titleKey);
        if(!ex){
          data.tracks.push({id:'WP-PLY-'+Math.random().toString(36).slice(2,8),title:pt.title,artist:resolvedArtist,status:'QC Review',score:0,rotation:resolvedArtist==='NMC SIGNAL'?'D':'B',streams:0,genre:pt.genre||'',bpm:pt.bpm||'',audioUrl:pt.url||pt.audio_url||'',coverUrl:pt.cover||'',wpSynced:true,scores:structuredClone(blankScores),rightsData:baseRights(pt.title,resolvedArtist),generations:[],dna:{title:pt.title,artist:resolvedArtist,emotion:'',explicit:'Explicit',conflict:'',transformation:'',hook:'',anchor:'',purpose:'',bpm:Number(pt.bpm)||138,key:'',risks:''}});
          added++;
        } else {
          if(_betterArtist(resolvedArtist,ex.artist))ex.artist=resolvedArtist;
          if(pt.url&&!ex.audioUrl)ex.audioUrl=pt.url;
          if(pt.cover&&!ex.coverUrl)ex.coverUrl=pt.cover;
          if(!ex.wpSynced){ex.wpSynced=true;updated++;}
        }
      });
    }
    // Purge duplicates created by previous syncs
    const removed=_deduplicateTracks();
    if(removed)updated+=removed;
    if(added||updated){
      save();renderOverview();renderPipeline();renderRotation();renderTrackSelector();
      if(!silent)toast(`Sync: +${added} added, ${updated} updated/deduped from nairamusic.com`);
    } else if(!silent){toast('Sync complete — catalogue clean, no changes');}
  }catch(e){if(!silent)toast('Track sync failed: '+e.message);}
}
// ── TRACK SYNC RENDERED BY ARTIST ──────────────────────────────────────────
function renderTracksByArtist(){
  const panel=$('#tracksByArtistPanel');if(!panel)return;
  const artistGroups={};
  data.tracks.forEach(t=>{
    const key=t.artist||'Unknown';
    if(!artistGroups[key])artistGroups[key]=[];
    artistGroups[key].push(t);
  });
  const artists=data.artists.map(a=>a.name);
  const sortedKeys=[...artists.filter(n=>artistGroups[n]),...Object.keys(artistGroups).filter(k=>!artists.includes(k))];
  panel.innerHTML=sortedKeys.length?sortedKeys.map(artist=>{
    const tracks=artistGroups[artist]||[];
    const a=data.artists.find(x=>x.name===artist);
    return `<section class="artist-track-group">
      <div class="atg-head">
        <div><b>${artist}</b>${a?`<small>${a.archetype}</small>`:'<small>External / No Bible</small>'}</div>
        <span class="tag">${tracks.length} TRACK${tracks.length===1?'':'S'}</span>
      </div>
      ${tracks.map(t=>`<div class="atg-row">
        <div class="atg-info"><b>${t.title}</b><small>${t.genre||'—'}${t.bpm?' · '+t.bpm+' BPM':''} · ${t.status}${t.streams?' · '+(t.streams||0).toLocaleString()+' streams':''}</small></div>
        <div class="atg-actions">
          <span class="rotation-badge tier-${(t.rotation||'E').toLowerCase()}">${t.rotation||'E'}</span>
          ${t.score?`<span class="tag">${t.score}</span>`:''}
          ${t.wpSynced?'<span class="tag" style="color:var(--green);border-color:#28583a">SITE</span>':''}
          ${t.audioUrl?`<a href="${t.audioUrl}" target="_blank" rel="noopener" class="button ghost small">▶</a>`:''}
        </div>
      </div>`).join('')}
    </section>`;
  }).join(''):'<p class="radio-empty">No tracks loaded. Sync from nairamusic.com to populate.</p>';
}
